    }

    /**
     * 覆盖区段集合规范化：去空白、去重、字典序排序，换序视为同参。
     */
    public static List<String> normalizeSections(List<String> sections) {
        TreeSet<String> normalized = new TreeSet<>();
        for (String s : sections) {
