     */
    private void assignCrew(long planId, CrewAssignmentRequest driver,
                            CrewAssignmentRequest conductor, long nowMillis) {
        if (driver != null) {
            crewRepo.upsertPlanCrew(planId, CrewRole.DRIVER, driver.crewId(), driver.qualCode(),
                    nowMillis);
